# owner: platform
"""Arrange students into text rows for a seating chart."""

from typing import List
from rosterkit.models import Student
from operator import attrgetter

# ---
def seat_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    if seats_per_row <= 0 or not students:
        raise ValueError("need students and positive seats")
    ordered = sorted(students, key=attrgetter("last_name"))
    return _layout(ordered, seats_per_row)

def _layout(
    ordered: List[Student], seats_per_row: int
) -> List[str]:
    rows = []
    for start in range(0, len(ordered), seats_per_row):
        seated = ordered[start:start + seats_per_row]
        rows.append(_row_text(len(rows) + 1, seated))
    return rows

def _row_text(number: int, seated: List[Student]) -> str:
    names = [student.display_name for student in seated]
    return f"Row {number}: {' | '.join(names)}"

