# owner: platform
"""Tests for the seating chart rows."""

import unittest
from rosterkit.seating import seat_rows
from rosterkit.models import Student

def _student(last_name: str, first_name: str) -> Student:
    return Student("id", last_name, first_name, "A")

class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.juno = _student("Halloway", "Juno")
        self.piet = _student("Dunmere", "Piet")
        self.lu = _student("Ames", "Lu")

    def test_sorted_by_last_name_within_a_row(self):
        rows = seat_rows([self.juno, self.piet], 2)
        expected = ["Row 1: Dunmere, Piet | Halloway, Juno"]
        self.assertEqual(rows, expected)

    def test_new_row_after_each_seat_count(self):
        rows = seat_rows([self.juno, self.piet, self.lu], 2)
        expected = [
            "Row 1: Ames, Lu | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ]
        self.assertEqual(rows, expected)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([self.juno], 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([self.juno], -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
